import datetime,json,hashlib,pathlib,subprocess
R=pathlib.Path('/repos/Antigravity/typst-crystalline');H=pathlib.Path(__file__).resolve().parent;out=H/'context-investigation';assert not out.exists();out.mkdir();sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();git=lambda *a:subprocess.check_output(['git',*a],cwd=R,text=True)
P=R/'lab/target/product/debug/typst';O=R/'lab/typst-original/target/release/typst';B=R/'lab/results/v16-corrections-2026-10-19/circle-origin/candidate-build-receipt.json';assert sha(P)in B.read_text()
base='#let c = circle(radius:2em)\n#set text(size:10pt)\n#context [#metadata(measure(c)) <probe>]\n#set text(size:20pt)\n#context [#metadata(measure(c)) <probe>]\n'
cases={'shared-circle':base,'distinct-circle':base.replace('measure(c)','measure(circle(radius:2em))'),'shared-rect':base.replace('circle(radius:2em)','rect(width:4em,height:4em)'),'shared-text':base.replace('circle(radius:2em)','[X]'),'direct-metadata':'#metadata(40) <probe>\n#metadata(80) <probe>\n','two-context-constants':'#context [#metadata(40) <probe>]\n#context [#metadata(80) <probe>]\n','same-context-constants':'#context [#metadata(40) <probe>]\n#context [#metadata(40) <probe>]\n','same-context-countereffect':'#context [#metadata(here().position()) <probe>]\n#v(20pt)\n#context [#metadata(here().position()) <probe>]\n','shared-circle-unique-tags':base.replace(' <probe>]', ' <a>]',1).replace(' <probe>]',' <b>]'),'shared-circle-different-body':base.replace('measure(c)) <probe>]\n', '(tag:1, value:measure(c))) <probe>]\n',1),'combined-scope': '#let c = circle(radius:2em)\n#context [#set text(size:10pt)\n#metadata(measure(c)) <probe>\n#set text(size:20pt)\n#metadata(measure(c)) <probe>]\n','shared-circle-blocks':'#let c=circle(radius:2em)\n#block[#set text(size:10pt)\n#context [#metadata(measure(c)) <probe>]]\n#block[#set text(size:20pt)\n#context [#metadata(measure(c)) <probe>]]\n'}
rec={'utc_start':datetime.datetime.now(datetime.timezone.utc).isoformat(),'head':git('rev-parse','HEAD').strip(),'diff_head_stat':git('diff','HEAD','--stat'),'binaries':{'product':{'path':str(P),'sha256':sha(P)},'oracle':{'path':str(O),'sha256':sha(O)}},'build_receipt_sha256':sha(B),'cases':[]}
for name,source in cases.items():
 p=out/(name+'.typ');p.write_text(source);c={'name':name,'source':source,'source_sha256':sha(p),'results':{}}
 for label,binary in [('product',P),('oracle',O)]:
  selector='metadata' if name=='shared-circle-unique-tags' else '<probe>';argv=[str(binary),'query',str(p),selector,'--field','value'];s=subprocess.run(argv,cwd=R,capture_output=True,text=True,timeout=30);c['results'][label]={'argv':argv,'returncode':s.returncode,'stdout':s.stdout,'stderr':s.stderr}
 rec['cases'].append(c)
rec.update(utc_end=datetime.datetime.now(datetime.timezone.utc).isoformat(),diff_head_stat_after=git('diff','HEAD','--stat'),binary_sha256_after={'product':sha(P),'oracle':sha(O)});(out/'receipt.json').write_text(json.dumps(rec,indent=2)+'\n')
for c in rec['cases']:print(c['name'],[(k,v['returncode'],v['stdout'].strip())for k,v in c['results'].items()])
